        public IEnumerator UpgradeItem(string playerItemId,
            Action<UpgradeItemResponse> onSuccess, Action<string> onError)
        {
            var req = new UpgradeItemRequest { playerItemId = playerItemId };
            yield return AuthenticatedPost<UpgradeItemResponse>(
                Cfg.GameInventoryUpgrade, JsonUtility.ToJson(req), onSuccess, onError);
        }

        #endregion

        #region Generic Request Helpers

        /// <summary>
        /// Sends an authenticated GET request. On 401, refreshes token and retries once.
        /// </summary>
        private IEnumerator AuthenticatedGet<T>(string endpoint,
            Action<T> onSuccess, Action<string> onError) where T : class
        {
            if (!EnsureAuth(onError)) yield break;

            // Proactively refresh if about to expire
            if (NeedsTokenRefresh)
            {
                bool refreshDone = false;
                yield return RefreshToken(_ => refreshDone = true, _ => refreshDone = true);
                yield return new WaitUntil(() => refreshDone);
            }

            using (var www = CreateGetRequest(endpoint))
            {
                yield return www.SendWebRequest();

                if (www.responseCode == 401)
                {
                    // Token expired — try refresh and retry
                    yield return RetryAfterRefresh<T>(
                        () => CreateGetRequest(endpoint), onSuccess, onError);
                    yield break;
                }

                if (www.result == UnityWebRequest.Result.Success)
                {
                    var resp = TryParse<T>(www.downloadHandler.text);
                    if (resp != null)
                        onSuccess?.Invoke(resp);
                    else
                        onError?.Invoke("Failed to parse response");
                }
                else
                {
                    HandleRequestError(www, onError);
                }
            }
        }

        /// <summary>
        /// Sends an authenticated POST request. On 401, refreshes token and retries once.
        /// </summary>
        private IEnumerator AuthenticatedPost<T>(string endpoint, string jsonBody,
            Action<T> onSuccess, Action<string> onError) where T : class
        {
            if (!EnsureAuth(onError)) yield break;

            if (NeedsTokenRefresh)
            {
                bool refreshDone = false;
                yield return RefreshToken(_ => refreshDone = true, _ => refreshDone = true);
                yield return new WaitUntil(() => refreshDone);
            }

            using (var www = CreatePostRequest(endpoint, jsonBody))
            {
                yield return www.SendWebRequest();

                if (www.responseCode == 401)
                {
                    yield return RetryAfterRefresh<T>(
                        () => CreatePostRequest(endpoint, jsonBody), onSuccess, onError);
                    yield break;
                }

                if (www.result == UnityWebRequest.Result.Success)
                {
                    var resp = TryParse<T>(www.downloadHandler.text);
                    if (resp != null)
                        onSuccess?.Invoke(resp);
                    else
                        onError?.Invoke("Failed to parse response");
                }
                else
                {
                    HandleRequestError(www, onError);
                }
            }
        }

        /// <summary>Refresh token and retry the request once.</summary>
        private IEnumerator RetryAfterRefresh<T>(Func<UnityWebRequest> requestFactory,
            Action<T> onSuccess, Action<string> onError) where T : class
        {
            Log("<color=#FFFF00>Got 401 — refreshing token and retrying...</color>");

            bool refreshDone = false;
            bool refreshOk = false;
            yield return RefreshToken(
                _ => { refreshOk = true; refreshDone = true; },
                _ => { refreshDone = true; });
            yield return new WaitUntil(() => refreshDone);

            if (!refreshOk)
            {
                onError?.Invoke("Authentication expired and refresh failed");
                yield break;
            }

            using (var www = requestFactory())
            {
                yield return www.SendWebRequest();
                if (www.result == UnityWebRequest.Result.Success)
                {
                    var resp = TryParse<T>(www.downloadHandler.text);
                    if (resp != null)
                        onSuccess?.Invoke(resp);
                    else
                        onError?.Invoke("Failed to parse response after retry");
                }
                else
                {
                    HandleRequestError(www, onError);
                }
            }
        }

        #endregion

        #region HTTP Helpers

        private string BaseUrl => _config?.BaseUrl ?? "https://api-dev.wattstap.energy";
        private int RequestTimeout => _config?.RequestTimeout ?? 30;
        private int BufferSeconds => _config?.TokenRefreshBufferSeconds ?? 60;
        private CoreServerConfig Cfg => _config;

        private UnityWebRequest CreateGetRequest(string endpoint, bool useAuth = true)
        {
            var www = UnityWebRequest.Get(BaseUrl + endpoint);
            www.timeout = RequestTimeout;
            if (useAuth && IsAuthenticated)
                www.SetRequestHeader("Authorization", $"Bearer {_authToken}");
            return www;
        }

        private UnityWebRequest CreatePostRequest(string endpoint, string jsonBody, bool useAuth = true)
        {
            var www = new UnityWebRequest(BaseUrl + endpoint, "POST");
            www.timeout = RequestTimeout;
            byte[] bodyRaw = Encoding.UTF8.GetBytes(jsonBody);
            www.uploadHandler = new UploadHandlerRaw(bodyRaw);
            www.downloadHandler = new DownloadHandlerBuffer();
            www.SetRequestHeader("Content-Type", "application/json");
            if (useAuth && IsAuthenticated)
                www.SetRequestHeader("Authorization", $"Bearer {_authToken}");
            return www;
        }

        private bool EnsureAuth(Action<string> onError)
        {
            if (!IsAuthenticated)
            {
                onError?.Invoke("Not authenticated");
                return false;
            }
            return true;
        }

        private void HandleRequestError(UnityWebRequest www, Action<string> onError)
        {
            string errorMessage = www.error;
            if (!string.IsNullOrEmpty(www.downloadHandler?.text))
            {
                try
                {
                    var err = JsonUtility.FromJson<ApiErrorResponse>(www.downloadHandler.text);
                    if (!string.IsNullOrEmpty(err?.detail))
                        errorMessage = err.detail;
                }
                catch { /* use default */ }
            }
            Debug.LogError($"{Tag} Request failed [{www.responseCode}]: {errorMessage}");
            onError?.Invoke(errorMessage);
        }

        private T TryParse<T>(string json) where T : class
        {
            try
            {
                Log($"Response: {(json.Length > 500 ? json.Substring(0, 500) + "..." : json)}");
                return JsonUtility.FromJson<T>(json);
            }
            catch (Exception ex)
            {
                Debug.LogError($"{Tag} JSON parse error: {ex.Message}");
                return null;
            }
        }

        #endregion

        #region Token Management

        private void StoreToken(string token, int expiresInSeconds)
        {
            _authToken = token;
            _tokenExpiresAt = DateTime.UtcNow.AddSeconds(expiresInSeconds);

            _sharedDataService?.SetData(SharedDataConstants.CoreAuthToken, token);
            _sharedDataService?.SetData(SharedDataConstants.CoreTokenExpiresAt, _tokenExpiresAt);

            // Also store in legacy key so other services can read it
            _sharedDataService?.SetData(SharedDataConstants.ReferralAuthToken, token);
        }

        private void UpdateEnergyFromState(PlayerStateDTO playerState)
        {
            if (playerState == null) return;
            _currentEnergy = playerState.energy;
            _sharedDataService?.SetData(SharedDataConstants.PlayerEnergy, _currentEnergy);
            _sharedDataService?.SetData(SharedDataConstants.PlayerState, playerState);
        }

        private IEnumerator AutoRefreshCoroutine()
        {
            float checkInterval = _config?.RefreshCheckInterval ?? 30f;
            while (true)
            {
                yield return new WaitForSeconds(checkInterval);

                if (!IsAuthenticated) continue;

                if (NeedsTokenRefresh)
                {
                    Log("Auto-refresh: token is about to expire, refreshing...");
                    bool done = false;
                    yield return RefreshToken(
                        _ => done = true,
                        err =>
                        {
                            Debug.LogError($"{Tag} Auto-refresh failed: {err}");
                            done = true;
                        });
                    yield return new WaitUntil(() => done);
                }
            }
        }

        #endregion

        #region Logging

        private void Log(string message)
        {
            if (_config == null || _config.DebugLogging)
                Debug.Log($"<color=#00FFCC>{Tag} {message}</color>");
        }

        #endregion
    }
}

using System;
using System.Collections.Generic;

namespace WattsTap.Core.API
{
    // ──────────────────────────────────────────────
    //  Catalog DTOs  (GET /game/items/catalog)
    // ──────────────────────────────────────────────

    [Serializable]
    public class CatalogResponse
    {
        public List<CatalogItemDTO> items;
    }

    [Serializable]
    public class CatalogItemDTO
    {
        public string id;
        public string code;
        public string name;
        public string description;
        public string slot;
        public List<CatalogVariantDTO> variants;
    }

    [Serializable]
    public class CatalogVariantDTO
    {
        public string id;
        public string rarity;
        public int maxLevel;
        public string mainStatType;
        public List<CatalogLevelDTO> levels;
        public List<CatalogBonusDTO> bonuses;
    }

    [Serializable]
    public class CatalogLevelDTO
    {
        public int level;
        /// <summary>Flat value. Server sends null for some stats → defaults to 0.</summary>
        public float value;
        /// <summary>Percentage value. Server sends null for some stats → defaults to 0.</summary>
        public float valuePercent;
    }

    [Serializable]
    public class CatalogBonusDTO
    {
        public string statType;
        public float value;
        public float valuePercent;
        public string description;
    }

    // ──────────────────────────────────────────────
    //  Inventory DTOs  (GET /game/inventory)
    // ──────────────────────────────────────────────

    [Serializable]
    public class InventoryResponse
    {
        public List<PlayerInventoryItemDTO> inventory;
        public EquipmentSlotsDTO equipment;
        public EquippedStatsMapDTO equippedStats;
        public CurrenciesDTO currencies;
    }

    [Serializable]
    public class PlayerInventoryItemDTO
    {
        public string id;            // Player-item instance id
        public string itemId;        // Template item id
        public string variantId;     // Variant id (rarity-specific)
        public int level;
        public string slot;
        public string rarity;
        public string name;
        public string code;
        public string mainStatType;
        public bool isEquipped;
    }

    [Serializable]
    public class EquipmentSlotsDTO
    {
        public string WEAPON;
        public string ARMS;
        public string BODY;
        public string FEET;
    }

    [Serializable]
    public class EquippedStatsMapDTO
    {
        public StatValueDTO COINS_PER_TAP;
        public StatValueDTO XP_PER_TAP;
        public StatValueDTO CAPACITY_HITS;
        public StatValueDTO RECOVER_HITS_PER_SECOND;
        public StatValueDTO CRIT_CHANCE;
        public StatValueDTO CRIT_MULTIPLIER;
        public StatValueDTO OFFLINE_BONUS_PERCENT;
    }

    [Serializable]
    public class StatValueDTO
    {
        public float value;
        public float valuePercent;
    }

    [Serializable]
    public class CurrenciesDTO
    {
        public long coins;
        public long drawings;
    }

    // ──────────────────────────────────────────────
    //  Equip / Unequip / Upgrade DTOs
    // ──────────────────────────────────────────────

    [Serializable]
    public class EquipItemRequest
    {
        public string playerItemId;
    }

    [Serializable]
    public class UnequipItemRequest
    {
        public string slot;
    }

    [Serializable]
    public class UpgradeItemRequest
    {
        public string playerItemId;
    }

    [Serializable]
    public class EquipItemResponse
    {
        public bool success;
        public InventoryResponse inventory;
    }

    [Serializable]
    public class UnequipItemResponse
    {
        public bool success;
        public InventoryResponse inventory;
    }

    [Serializable]
    public class UpgradeItemResponse
    {
        public bool success;
        public PlayerInventoryItemDTO item;
        public CurrenciesDTO currencies;
    }
}

using System;
using System.Collections;

namespace WattsTap.Core.API
{
    /// <summary>
    /// Service for communicating with the new Core API server (api-dev.wattstap.energy).
    /// Handles authentication, token refresh, progress (tap-based), avatars, social, user profile.
    /// </summary>
    public interface ICoreServerService : IService
    {
        #region Auth State

        /// <summary>JWT auth token</summary>
        string AuthToken { get; }

        /// <summary>Whether the user is authenticated</summary>
        bool IsAuthenticated { get; }

        /// <summary>When the current token expires</summary>
        DateTime TokenExpiresAt { get; }

        /// <summary>Whether the token needs to be refreshed soon</summary>
        bool NeedsTokenRefresh { get; }

        /// <summary>Current player energy from last server response</summary>
        int CurrentEnergy { get; }

        #endregion

        #region Auth

        /// <summary>Authenticate via Telegram initData</summary>
        IEnumerator Authenticate(string initData, string referralCode,
            Action<AuthResponse> onSuccess, Action<string> onError);

        /// <summary>Refresh the JWT token (uses cookie-based refresh or re-auth fallback)</summary>
        IEnumerator RefreshToken(Action<AuthResponse> onSuccess, Action<string> onError);

        /// <summary>Logout and invalidate tokens</summary>
        IEnumerator Logout(Action<LogoutResponse> onSuccess, Action<string> onError);

        /// <summary>Start automatic token refresh coroutine</summary>
        void StartAutoRefresh(UnityEngine.MonoBehaviour coroutineRunner);

        /// <summary>Stop automatic token refresh</summary>
        void StopAutoRefresh();

        #endregion

        #region User

        /// <summary>Get current user profile and events</summary>
        IEnumerator GetUserMe(Action<UserMeResponse> onSuccess, Action<string> onError);

        /// <summary>Update user language</summary>
        IEnumerator UpdateLanguage(string langCode,
            Action<UpdateLanguageResponse> onSuccess, Action<string> onError);

        /// <summary>Mark events as read</summary>
        IEnumerator MarkEventsRead(MarkEventsReadRequest request,
            Action<MarkEventsReadResponse> onSuccess, Action<string> onError);

        #endregion

        #region Progress (Tap-based)

        /// <summary>Load player progress from server</summary>
        IEnumerator LoadProgress(Action<ExtendedLoadProgressResponse> onSuccess, Action<string> onError);

        /// <summary>Send taps to server (new tap-based model)</summary>
        IEnumerator SendTaps(int tapCount,
            Action<TapProgressResponse> onSuccess, Action<string> onError);

        /// <summary>Reset player progress</summary>
        IEnumerator ResetProgress(Action<ResetProgressResponse> onSuccess, Action<string> onError);

        #endregion

        #region Mining Balance

        /// <summary>Load mining balance config (public, no auth needed)</summary>
        IEnumerator LoadMiningBalance(Action<MiningBalancePublicResponse> onSuccess, Action<string> onError);

        #endregion

        #region Avatars

        /// <summary>Get player's avatars including full catalog</summary>
        IEnumerator GetAvatars(Action<GetAvatarsResponse> onSuccess, Action<string> onError);

        /// <summary>Purchase an avatar with currency</summary>
        IEnumerator PurchaseAvatar(PurchaseAvatarRequest request,
            Action<PurchaseAvatarResponse> onSuccess, Action<string> onError);

        /// <summary>Claim a free avatar (replaces unlock-by-level)</summary>
        IEnumerator ClaimAvatar(string avatarId,
            Action<ClaimAvatarResponse> onSuccess, Action<string> onError);

        #endregion

        #region Social / Referral

        /// <summary>Get user's referral information</summary>
        IEnumerator GetMyReferral(Action<MyReferralResponse> onSuccess, Action<string> onError);

        /// <summary>Get user's friends list</summary>
        IEnumerator GetFriends(Action<FriendsListResponse> onSuccess, Action<string> onError);

        /// <summary>Claim referral bonus</summary>
        IEnumerator ClaimReferralBonus(Action<ClaimBonusResponse> onSuccess, Action<string> onError);

        /// <summary>Apply a referral code manually</summary>
        IEnumerator ApplyReferralCode(string referralCode, string source,
            Action<ReferralApplyResponse> onSuccess, Action<string> onError);

        #endregion
    }
}

